// Client-side site search for /search/. The index is /search-index.json,
// generated by scripts/update-homepage-insights.js — see CLAUDE.md.
(() => {
  const input = document.getElementById('search-input');
  const status = document.getElementById('search-status');
  const results = document.getElementById('search-results');
  if (!input || !status || !results) return;

  const MAX_RESULTS = 25;
  const SNIPPET_RADIUS = 90;
  let entries = null;

  // Lowercase, fold accents and curly quotes so "don't" matches "don’t".
  const normalize = (s) =>
    s
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/[‘’]/g, "'")
      .replace(/[“”]/g, '"');

  const escapeHtml = (s) =>
    s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Same "25 Nov 2026" format scripts/update-homepage-insights.js writes.
  const formatDate = (iso) => {
    const [y, m, d] = iso.split('-').map(Number);
    return `${d} ${MONTHS[m - 1]} ${y}`;
  };

  const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const terms = (query) =>
    [...new Set(normalize(query).replace(/["]/g, ' ').split(/\s+/).filter((t) => t.length > 1 || /\d/.test(t)))];

  const count = (haystack, term) => {
    let n = 0;
    let i = haystack.indexOf(term);
    while (i !== -1 && n < 20) {
      n += 1;
      i = haystack.indexOf(term, i + term.length);
    }
    return n;
  };

  function prepare(raw) {
    return raw.map((e) => ({
      ...e,
      n: {
        title: normalize(e.title),
        tag: normalize(e.tag || ''),
        description: normalize(e.description || ''),
        text: normalize(e.text || ''),
      },
    }));
  }

  function score(entry, words, phrase) {
    const { title, tag, description, text } = entry.n;
    let total = 0;
    for (const w of words) {
      const inTitle = title.includes(w);
      const inTag = tag.includes(w);
      const inDesc = description.includes(w);
      const hits = count(text, w);
      if (!inTitle && !inTag && !inDesc && !hits) return 0; // every word must appear
      const wordStart = new RegExp(`(^|[^a-z0-9])${escapeRe(w)}`);
      total += (inTitle ? (wordStart.test(title) ? 12 : 6) : 0) + (inTag ? 5 : 0) + (inDesc ? 4 : 0) + Math.min(hits, 10);
    }
    if (words.length > 1) {
      if (title.includes(phrase)) total += 20;
      else if (description.includes(phrase)) total += 10;
      else if (text.includes(phrase)) total += 6;
    }
    return total;
  }

  // Snippets are cut from the original text; normalize() keeps one char per
  // char for everything this site uses, so offsets line up.
  function snippet(entry, words, phrase) {
    const source = entry.text || entry.description || '';
    const haystack = entry.n.text || entry.n.description;
    let at = words.length > 1 ? haystack.indexOf(phrase) : -1;
    if (at === -1) {
      const firsts = words.map((w) => haystack.indexOf(w)).filter((i) => i !== -1);
      at = firsts.length ? Math.min(...firsts) : -1;
    }
    if (at === -1) return highlight(entry.description || '', words);
    let start = Math.max(0, at - SNIPPET_RADIUS);
    let end = Math.min(source.length, at + SNIPPET_RADIUS * 2);
    if (start > 0) start = source.indexOf(' ', start) + 1 || start;
    if (end < source.length) end = source.lastIndexOf(' ', end) || end;
    return (start > 0 ? '… ' : '') + highlight(source.slice(start, end), words) + (end < source.length ? ' …' : '');
  }

  function highlight(text, words) {
    if (!words.length) return escapeHtml(text);
    const norm = normalize(text);
    const marks = new Array(text.length).fill(false);
    for (const w of words) {
      let i = norm.indexOf(w);
      while (i !== -1) {
        for (let k = i; k < i + w.length && k < marks.length; k += 1) marks[k] = true;
        i = norm.indexOf(w, i + w.length);
      }
    }
    let out = '';
    let open = false;
    for (let i = 0; i < text.length; i += 1) {
      if (marks[i] && !open) { out += '<mark>'; open = true; }
      if (!marks[i] && open) { out += '</mark>'; open = false; }
      out += escapeHtml(text[i]);
    }
    return open ? out + '</mark>' : out;
  }

  function render(query) {
    const words = terms(query);
    if (!words.length) {
      results.innerHTML = '';
      status.textContent = query.trim() ? 'Type a longer search term.' : `Search across ${entries.length} articles and pages.`;
      return;
    }
    const phrase = words.join(' ');
    const matches = entries
      .map((e) => ({ e, s: score(e, words, phrase) }))
      .filter((m) => m.s > 0)
      .sort((a, b) => b.s - a.s || (b.e.date || '').localeCompare(a.e.date || ''));

    if (!matches.length) {
      results.innerHTML = '';
      status.textContent = `No results for “${query.trim()}”. Try fewer or different words.`;
      return;
    }

    status.textContent = `${matches.length} result${matches.length === 1 ? '' : 's'} for “${query.trim()}”` +
      (matches.length > MAX_RESULTS ? ` — showing the top ${MAX_RESULTS}.` : '.');
    results.innerHTML = matches
      .slice(0, MAX_RESULTS)
      .map(({ e }) => `
        <div class="insight-item">
          <div class="insight-date">${e.date ? `<time datetime="${escapeHtml(e.date)}">${formatDate(e.date)}</time> ` : ''}${escapeHtml(e.readTime || 'Page')}</div>
          <div>
            <span class="tag">${escapeHtml(e.tag || '')}</span>
            <h3><a href="${escapeHtml(e.url)}">${highlight(e.title, words)}</a></h3>
            <p>${snippet(e, words, phrase)}</p>
          </div>
        </div>`)
      .join('');
  }

  function syncUrl(query) {
    const url = new URL(window.location.href);
    if (query.trim()) url.searchParams.set('q', query.trim());
    else url.searchParams.delete('q');
    window.history.replaceState(null, '', url);
  }

  let timer;
  input.addEventListener('input', () => {
    window.clearTimeout(timer);
    timer = window.setTimeout(() => {
      syncUrl(input.value);
      if (entries) render(input.value);
    }, 120);
  });
  input.form?.addEventListener('submit', (event) => {
    event.preventDefault();
    syncUrl(input.value);
    if (entries) render(input.value);
  });

  input.value = new URLSearchParams(window.location.search).get('q') || '';
  status.textContent = 'Loading search index…';

  fetch('/search-index.json')
    .then((res) => {
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    })
    .then((data) => {
      entries = prepare(data.entries || []);
      render(input.value);
    })
    .catch(() => {
      status.textContent = 'Search is temporarily unavailable. Browse all articles on the Insights page.';
    });
})();
